public async Task<WebhookOutcome> HandleWebhookAsync(string payload, string signatureHeader)
{
    // Fetch live Stripe config from DB for webhook verification.
    var stripe = await GetStripeAsync();

    // Spec: when Stripe is not enabled, surface 503 to Stripe so its retry queue makes the misconfig loud.
    if (!stripe.Enabled)
    {
        _logger.LogWarning("Stripe webhook hit but Stripe is disabled. Returning Disabled (controller maps to 503).");
        return WebhookOutcome.Disabled;
    }

    Event stripeEvent;
    try
    {
        // throwOnApiVersionMismatch: false — Stripe events arrive formatted with the studio's account
        // default API version, which may not match Stripe.net's compiled-against version. The signature
        // is what matters for security; the version mismatch is informational, not actionable.
        stripeEvent = EventUtility.ConstructEvent(payload, signatureHeader, stripe.WebhookSecret, throwOnApiVersionMismatch: false);
    }
    catch (StripeException ex)
    {
        _logger.LogWarning(ex, "Stripe webhook signature verification failed.");
        return WebhookOutcome.BadSignature;
    }
    catch (Exception ex)
    {
        // Malformed / unparseable payload — treat as a bad request (400) rather
        // than letting it bubble to a 500, which would make Stripe hammer the
        // endpoint with retries. Real Stripe events always parse cleanly.
        _logger.LogWarning(ex, "Stripe webhook payload could not be parsed.");
        return WebhookOutcome.BadSignature;
    }

    // Idempotency: short-circuit on already-processed event ids. The unique index gives us a second line of defence;
    // see the catch on duplicate-key insertion further down for the race-window case.
    var alreadyProcessed = await _processedEvents.Find(e => e.EventId == stripeEvent.Id).AnyAsync();
    if (alreadyProcessed)
    {
        _logger.LogInformation("Stripe event {EventId} ({EventType}) already processed — skipping replay.", stripeEvent.Id, stripeEvent.Type);
        return WebhookOutcome.Replayed;
    }

    // Apply side-effects per event type. Whitelist of supported events:
    var sideEffectApplied = false;
    string? relatedObjectId = null;

    switch (stripeEvent.Type)
    {
        case "payment_intent.succeeded":
        {
            if (stripeEvent.Data.Object is PaymentIntent intent)
            {
                relatedObjectId = intent.Id;

                // Route on the intent metadata `kind`. Legacy intents (created
                // before Issue #2 wired in the discriminator) have no `kind`
                // entry — default them to attendance_booking to preserve
                // existing behaviour during deploy.
                var kind = intent.Metadata != null && intent.Metadata.TryGetValue("kind", out var k) && !string.IsNullOrWhiteSpace(k)
                    ? k
                    : "attendance_booking";

                if (kind == "package_purchase")
                {
                    var marked = await MarkInvoicePaidAsync(intent.Id);
                    _logger.LogInformation("Stripe webhook processed payment_intent.succeeded (package_purchase) {PaymentIntentId} (marked={Marked}).", intent.Id, marked);
                }
                else
                {
                    var marked = await MarkSucceededAsync(intent.Id);
                    _logger.LogInformation("Stripe webhook processed payment_intent.succeeded {PaymentIntentId} (marked={Marked}).", intent.Id, marked);
                }
                sideEffectApplied = true;
            }
            break;
        }
        case "payment_intent.payment_failed":
        {
            if (stripeEvent.Data.Object is PaymentIntent intent)
            {
                relatedObjectId = intent.Id;
                await _payments.UpdateOneAsync(
                    p => p.StripePaymentIntentId == intent.Id,
                    Builders<PaymentRecord>.Update.Set(p => p.Status, "FAILED"));
                _logger.LogInformation("Stripe webhook processed payment_intent.payment_failed {PaymentIntentId}.", intent.Id);
                sideEffectApplied = true;
            }
            break;
        }

