// ── Online Booking Invoice Creation ───────────────────────────────────────
// Creates a linked Invoice (+ initial Payment) for an online class booking.
// Idempotent: checks for an existing invoice linked to the attendance first.

/// <summary>
/// Creates an Invoice (and optionally a Payment) for an online class booking.
/// Idempotent — if an invoice already exists for the attendance, this is a no-op.
/// Called by CreateIntentAsync (PACKAGE_CREDIT) and MarkSucceededAsync (STRIPE).
/// </summary>
private async Task CreateBookingInvoiceAsync(
    Attendance attendance,
    CalendarSession session,
    decimal totalClassValue,
    decimal amountPaid,
    string paymentMethod,
    decimal onlineFeeAmount = 0m)
{
    if (string.IsNullOrWhiteSpace(attendance.Id)) return;

    // Idempotency: check if an invoice already exists for this attendance.
    var existingInvoice = await _invoices.Find(
        Builders<SoulPilates.Core.Entities.Invoice>.Filter.ElemMatch(
            i => i.Lines,
            Builders<InvoiceLine>.Filter.Eq(l => l.AttendanceId, attendance.Id)
        )
    ).FirstOrDefaultAsync();

    if (existingInvoice != null) return; // already created (webhook + confirm race)

    var quantity = Math.Max(1, attendance.Quantity);

    // ── PACKAGE_CREDIT: invoice at 0đ ────────────────────────────────
    // The class fee was already collected when the package was purchased.
    // Recording the class value again would double-count revenue.
    // The POS does the same: when "Use credit" is checked, price = 0đ.
    var isCredit = paymentMethod == "CREDIT";
    var unitPrice = isCredit ? 0m : (totalClassValue / quantity);
    var invoiceNotes = isCredit
        ? $"Online booking (package credit): {session.ClassName} on {StudioTime.Local(session.StartTime):yyyy-MM-dd HH:mm}"
        : $"Online booking (Stripe): {session.ClassName} on {StudioTime.Local(session.StartTime):yyyy-MM-dd HH:mm}";

    var invoice = new SoulPilates.Core.Entities.Invoice
    {
        ClientId = attendance.ClientId,
        TotalDiscount = 0m,
        TotalTax = 0m,
        IssueDate = DateTime.UtcNow,
        Notes = invoiceNotes,
        PaymentMethod = paymentMethod, // "CREDIT" or "STRIPE"
        OnlineFeeAmount = onlineFeeAmount,
        Lines = new List<InvoiceLine>
        {
            new InvoiceLine
            {
                ProductId = session.ClassBlueprintId ?? string.Empty,
                Quantity = quantity,
                UnitPrice = unitPrice,
                LineDiscount = 0m,
                AttendanceId = attendance.Id,
                CalendarSessionId = attendance.CalendarSessionId,
                ProductTypeSnapshot = "CLASS",
            }
        }
    };

    var created = await _invoiceService.CreateInvoiceAsync(invoice);

    // For Stripe payments, record the actual money collected.
    // STRIPE_FULL → PAID, STRIPE_DEPOSIT → PARTIAL.
    if (!isCredit && amountPaid > 0)
    {
        var payment = new Payment
        {
            AmountPaid = amountPaid,
            PaymentDate = DateTime.UtcNow,
            PaymentMethod = paymentMethod,
        };
        await _invoiceService.AddPaymentAsync(created.Id!, payment);
    }
    else if (isCredit)
    {
        // TotalNet is 0đ but CreateInvoiceAsync always initialises as UNPAID.
        // Flip to PAID directly — no Payment record because no money moved.
        await _invoices.UpdateOneAsync(
            i => i.Id == created.Id,
            Builders<SoulPilates.Core.Entities.Invoice>.Update.Set(i => i.Status, "PAID"));
    }

    _logger.LogInformation(
        "Created booking invoice {InvoiceNumber} for attendance {AttendanceId} (method={PaymentMethod}, classValue={ClassValue}, paid={AmountPaid}).",
        created.InvoiceNumber, attendance.Id, paymentMethod, totalClassValue, amountPaid);
}

// ── Issue #1 — Package Purchase Stripe Flow ──────────────────────────────
// CreatePackagePurchaseIntentAsync + MarkInvoicePaidAsync close the loop on
// *invoice*-anchored payments (vs. the attendance-anchored CreateIntentAsync
// / MarkSucceededAsync pair above). The webhook dispatcher picks between
// them via the `kind` metadata on the PaymentIntent.

